import crypto from "node:crypto";
import type { DefaultTreeAdapterTypes } from "parse5" with {
    "resolution-mode": "import",
};
import postcss, { type AtRule, type Declaration } from "postcss";
import type { StoredObject } from "@/ports/object-storage";

type HtmlNode = DefaultTreeAdapterTypes.Node;
type HtmlElement = DefaultTreeAdapterTypes.Element;
type HtmlText = DefaultTreeAdapterTypes.TextNode;

const CSS_CONTENT_TYPE = /^text\/css(?:;|$)/i;
const HTML_CONTENT_TYPE = /^text\/html(?:;|$)/i;
const URL_SOURCE = /url\(\s*(['"]?)([^)'"\s]+)\1\s*\)/gi;

function rewrittenObject(object: StoredObject, text: string): StoredObject {
    const body = new TextEncoder().encode(text);
    return {
        ...object,
        body,
        size: body.byteLength,
        etag: `"${crypto.createHash("sha256").update(body).digest("hex")}"`,
    };
}

function sourceUrls(rule: AtRule): string[] {
    const urls: string[] = [];
    rule.walkDecls(/^src$/i, (declaration: Declaration) => {
        for (const match of declaration.value.matchAll(URL_SOURCE)) {
            if (match[2]) urls.push(match[2]);
        }
    });
    return urls;
}

function isRemoteUrl(value: string): boolean {
    return /^(?:https?:)?\/\//i.test(value);
}

function optimizeStylesheet(object: StoredObject): StoredObject {
    const css = new TextDecoder().decode(object.body);
    const root = postcss.parse(css);
    let removed = 0;
    root.walkAtRules(/^font-face$/i, (rule) => {
        const urls = sourceUrls(rule);
        if (urls.length > 0 && urls.every(isRemoteUrl)) {
            rule.remove();
            removed += 1;
        }
    });
    return removed === 0 ? object : rewrittenObject(object, root.toString());
}

function importedUrl(rule: AtRule): string | null {
    const match = /^(?:url\(\s*)?(['"]?)([^'"\s)]+)\1\s*\)?/i.exec(
        rule.params.trim(),
    );
    return match?.[2] || null;
}

function isFontStylesheet(value: string): boolean {
    const pathname = value
        .split(/[?#]/, 1)[0]
        ?.replace(/\\/g, "/")
        .toLowerCase();
    return (
        pathname === "fonts.css" || pathname?.endsWith("/fonts.css") || false
    );
}

function isElement(node: HtmlNode): node is HtmlElement {
    return "tagName" in node;
}

function optimizeStyleElement(element: HtmlElement): boolean {
    const textNodes = element.childNodes.filter(
        (node): node is HtmlText => node.nodeName === "#text",
    );
    if (!textNodes.length) return false;
    const root = postcss.parse(textNodes.map((node) => node.value).join(""));
    let removed = 0;
    root.walkAtRules(/^import$/i, (rule) => {
        const url = importedUrl(rule);
        if (url && isFontStylesheet(url)) {
            rule.remove();
            removed += 1;
        }
    });
    if (removed === 0) return false;
    element.childNodes = [
        {
            nodeName: "#text",
            parentNode: element,
            value: root.toString(),
        },
    ];
    return true;
}

async function optimizeDocument(object: StoredObject): Promise<StoredObject> {
    const { parse, serialize } = await import("parse5");
    const document = parse(new TextDecoder().decode(object.body));
    let changed = false;
    const visit = (node: HtmlNode): void => {
        if (isElement(node) && node.tagName === "style") {
            changed = optimizeStyleElement(node) || changed;
        }
        if ("childNodes" in node) node.childNodes.forEach(visit);
    };
    visit(document);
    return changed ? rewrittenObject(object, serialize(document)) : object;
}

export async function optimizeSitePackageContent(
    object: StoredObject,
): Promise<StoredObject> {
    if (CSS_CONTENT_TYPE.test(object.contentType))
        return optimizeStylesheet(object);
    if (HTML_CONTENT_TYPE.test(object.contentType))
        return await optimizeDocument(object);
    return object;
}
